#!/usr/bin/env python3
from pathlib import Path
import json,html,hashlib
R=Path(__file__).resolve().parents[1];VERSION='1.0.2'
(R/'docs').mkdir(exist_ok=True)
old=json.loads(((R/'FEATURE_CATALOG.json') if (R/'FEATURE_CATALOG.json').is_file() else R.parent/'verification/FEATURE_CATALOG.json').read_text())['features']
changes={
'F27':('满载返矿与到场优先', '矿车/矿场支持独立自定义 ID 清单；不勾选自动识别，勾选后仅使用清单，空清单排除全部。矿车须有储矿容量，目标须在该矿车原有 Dock 清单内。设置即时生效与自动保存，提交前重新检查。满载己方矿车由外部 Planner 选择兼容矿场并排队。2格内已到场车可优先于4格外预约车：经统一 OreYield 原生 Move 让位，观察原版 Move 和预约释放后再 Enter。每矿场一轮一车、每载货任务最多被插一次，被插车保留下一轮优先。最多3次让位重试，未释放180帧退出；本轮360帧上限。不打断到场/卸货或手动接管，安全格不足时保留原排队。Runtime 复核原版状态后统一入单机 DoList / 联机 OutList，不直接写 radio。150ms/6帧及对局/手动版本检查保留。', 'assist/source/external_planner.h; ore_queue.h; external_orders_bridge.h; main.cpp'),
'F10':('一键维修和自动维修','仅维修己方受损且未处于维修/待确认状态的建筑。默认检查 YRpp ClickRepairable (+0x157A)；勾选“允许维修不可维修的建筑”后可放宽此类型限制。收集与提交前均检查，关掉许可会跳过未提交的非标准建筑请求；已入原版队列的事件不撤回。不改原版类型数据或归属，仍通过统一 Repair 事件入口。','assist/source/bridge.cpp; assist/source/auto_settings_ui.h'),
'F51':('图标持久缓存与绘制缓存','外部后台线程将实际读取到的图标/色盘保存到 cache/unit-icons，按游戏路径和资源指纹隔离；小资源校验内容，大型 MIX 等资源以大小与更新时间识别。规则、地图、资源或程序变化时换用新的缓存。记录按类型 ID、图标文件名和类别匹配，校验版本、长度、条数与校验和，损坏缓存忽略；临时文件写完后原子替换。新对局可复用磁盘图标，实时图标可读后校正；首次从未读取过的图标仍需等游戏载入。GDI 位图保留，图标或色盘变化才重建。','unit_monitor/source/icon_cache.h; sampler.h; main.cpp'),
'F04':('单一 GameRuntime 与游戏线程管理','EXE 通过统一 host_game_input 订阅消息入口；只有 GameRuntime.dll 进入游戏。游戏线程租约与忙碌拒绝保留，忙碌不伪造回执。','shared/source/host_game_input.h; shared/source/game_entry_manager.cpp'),
'F05':('禁止游戏代码补丁','管理器的 Patch 操作直接返回 PatchDenied；没有 VirtualProtect、跳板分配、原版函数入口或调用点改写。旧补丁登记地址仅作为历史资料。','shared/source/game_entry_manager.cpp; assist/source/input_patch.h'),
'F06':('统一消息与外部输入调度','每个游戏仅有管理器 WH_GETMESSAGE / WH_CALLWNDPROCRET 两个 Windows 消息订阅。宿主按 4 ms 目标轮询增强鼠标输入并保存捕获时对局、边沿、按下时修饰键与取消代次；上下文超过 150 ms 未续期则停采并清除，切局/菜单/失焦重新播种按键状态；战术控制目标间隔 16 ms。实际延迟取决于系统调度和游戏消息泵。','shared/source/host_game_input.h; assist/source/pointer_host.h'),
'F07':('统一请求、接续和事件提交','命令、选兵、外部规划、协同与增强输入使用同一 Shared 协议和同一游戏线程调度。观察到与点击目标格相符的原版 Move 状态后才追加 CS；不修改原版任务、事件字节或接收函数。请求没有独立 Hook。队列满保留未提交部分，已接收前缀不重发。','assist/source/pointer_intent.h; assist/source/pointer_bridge.h; assist/source/bridge.cpp'),
'F16':('信标清理与实验性地图揭示','地图全开默认未许可，须勾选“启用地图全开（实验性）”；宿主与 Runtime 均检查许可，关闭清除待处理请求，不回退已揭示地图。经统一管理器调用原版本地 UI 接口。恢复单机及多人地图揭示，仅作用于当前玩家；仍检查有效对局与地图数组，菜单/加载/观战不执行。它是本地显示调用，不构造模拟事件。','assist/source/bridge.cpp'),
'F15':('组合选兵与双按范围','多个兵种可配置同一个快捷键，注册时去重。单按合并选中屏幕内这些类型的己方单位，双按选全图；本局缺失类型跳过。宿主生成绑定本局的类型掩码，唯一 GameRuntime 在同一选兵请求里筛选全部对象，只清空一次再合并选区；无网络事件或新增 Hook。解绑某个兵种保留组内其他兵种。原有按普通武器选变体功能及其独立快捷键保留。普通功能快捷键默认拒绝冲突；勾选热键冲突时全部执行后可共享。','assist/source/type_hotkey.h; assist/source/type_bindings_ui.h; assist/source/type_select_bridge.h; assist/source/main.cpp'),
'F21':('逃生助手','仅跟踪选中的己方载具，取消选中且载具仍存活时停止跟踪。载具被毁后，对已观察到的存活乘员继续跟进。可部署乘员保留原版散开移动，散开跟踪窗口为 180 帧；每名乘员只要原版 CanDeploy 允许就在当前调度提交 Deploy，不等待同格其他乘员，也没有固定停稳两帧延迟。条件不满足时不发 Sleep 阻止散开。显式停止、取消、正常下车、归属变化或超时结束跟进；不创造幸存者。仅保留一个逃生开关。','assist/source/native_orders_bridge.h; assist/source/unload_policy.h'),
'F22':('自动 CS：原版移动后接续','保留右键原版移动。宿主捕获右键释放时的输入意图，Runtime 等待己方选中单位的 Move 与相同目的格可观察后，再经 nativeMission 追加一次 AttackMove。检查单位类型白名单、武器、对局、对象身份和新输入代次。没有改写原版 QueueMegaMission；不改鼠标谓词。','assist/source/pointer_host.h; assist/source/pointer_bridge.h; assist/source/auto_cs_bridge.h'),
'F23':('按键 CS','按住配置键配合独立配置的 CS 鼠标键（默认中键），留空则仅鼠标。配置为右键时接续原版 Move；直接攻击移动使用另一独立按钮（默认侧键 1）。Shift 右键规划不接续；聊天、菜单、失去前台或过期时拒绝。原版光标不再被强制改成 CS 光标。','assist/source/pointer_host.h; assist/source/pointer_bridge.h'),
'F24':('高级移动攻击','按住配置键配合本功能鼠标键（默认中键，均可配置）；右键模式确认原版 Move 后追加初始 AttackMove，再登记外部规划任务。后续目标选择仍在 EXE，回到统一管理器验证并提交。','assist/source/native_orders_bridge.h; assist/source/external_planner.h; assist/source/pointer_bridge.h'),
'F25':('磁电轮换攻击','配合独立磁电鼠标键（默认中键）；配置为右键时：确认原版 Move 后仅登记任务，不再替换原版移动。中键方式先发普通 Move 再登记。外部 Planner 读取出手/重装填证据轮换目标，每次攻击通过统一原版事件通道。没有武器选择或射击函数 Hook。','assist/source/native_orders_bridge.h; assist/source/external_planner.h; assist/source/magnetron_cycle.h'),
'F26':('新输入取消与手动优先','宿主观察右键按下以及 S/D/X 边沿，取消旧的未提交增强批次；有效取消请求按捕获的己方选区撤销工具任务。普通事件仍由游戏处理。状态观测继续识别原版任务变化。输入队列上限 16，超时不补发；短于轮询间隔的点击可能漏采，不会补造点击。','shared/source/host_game_input.h; assist/source/pointer_bridge.h; assist/source/object_index.h'),
'F30':('高级进驻建筑与载具','按住进驻配置键（默认 Alt）并按本功能鼠标键（默认中键）指向目标，捕获最多 512 个源对象，向现有外部协同分配器提交。按同类目标容量分配，Runtime 复核原版进入合法性后发送 Enter/Capture。超限拒绝增强请求，普通左右键仍原样运行。','assist/source/pointer_bridge.h; assist/source/cooperative_bridge.h; assist/source/extra_settings_io.h'),
'F31':('飞机高级攻击','按住对应攻击配置键并按本模式鼠标键（默认中键）指向敌方目标。目标分配、受击上限仍由外部协同规划器完成，GameRuntime 复核对象与武器兼容并构造 Attack 事件。不再拦截 FootClickedAction。','assist/source/cooperative_bridge.h; assist/source/extra_settings_io.h'),
'F33':('飞碟主武器','开启后 配置键（默认 Ctrl，可留空）+本功能鼠标键（默认中键）指向建筑，识别飞碟/吸取副武器类型并提交原版对地强制攻击事件。原版正常点击与武器选择保持原样；不直接修改武器、任务或目标。','assist/source/cooperative_bridge.h'),
'F34':('变卖受吸取的己方建筑','开启后 配置键（默认 Ctrl，可留空）+本功能鼠标键（默认侧键 2）指向己方受吸取建筑，经统一对象事件构造器提交 Sell。目标必须仍存活、归自己所有。无变卖模式/光标 Hook。','assist/source/cooperative_bridge.h; assist/source/pointer_bridge.h'),
'F35':('变卖己方载具','开启后 配置键（默认 Ctrl，可留空）+本功能鼠标键（默认侧键 2）指向载具。保留原版接收端条件：目标归发送玩家、载具格子中存在建筑。构造 Sell 对象事件，目标标签为 0x34。不会伪造其他玩家身份、改变格子链表或直接调用出售执行函数。模型执行了用户 EXE 的 Sell 接收分支，最终出售/经济效果仍待游戏实测。','assist/source/cooperative_bridge.h; assist/source/pointer_bridge.h'),
'F36':('变卖敌方建筑：停用','不再伪造敌方 House 发出 Sell。配置加载强制关闭、界面禁用、Runtime 再检查己方归属。','assist/source/extra_settings_io.h; assist/source/extra_controls.h; assist/source/cooperative_bridge.h'),
'F37':('随处建造：停用','该能力需要绕过原版放置合法性判断，普通移动/生产事件无法等价实现。删除 0x464AC0 拦截，旧配置不能恢复，Runtime 返回不支持。','assist/source/placement_bridge.h'),
'F39':('科技全开：生产连续性待修复','补图实验不能防止原版 Abandon/AbandonAll 取消生产，已撤出。删除两个原版侧栏 CanBuild 调用点改写，不补造无资格图标，不绕过前置科技。类型目录和条件解析保留。界面禁用科技全开，旧配置不能恢复。','assist/source/sidebar.h; assist/source/main.cpp'),
'F40':('合法生产与生产观测','外部生产仅限单机，提交前调用正常 CanBuild（limitOnly=false）并检查工厂；原生侧栏不被改写。生产完成/暂停观测以及本地图标闪烁保留。','assist/source/bridge.cpp; assist/source/sidebar.h'),
'F52':('Tab 显示与快捷键','删除单位统计自己的 WH_KEYBOARD_LL。改为现有 UI 时钟轮询 Tab，不吞原版 Tab，游戏原来的 Tab 行为会同时保留。Ctrl+Alt+H 和显示按钮可独立显隐；勾选常驻显示可完全不使用 Tab。失焦/菜单/读取无效仍隐藏，面板与日志说明原因。','unit_monitor/source/main.cpp'),
'F55':('原版光标隐藏/恢复','通过统一 GameRuntime 在绑定游戏线程调用原版鼠标对象 Hide/Show，跟踪配对引用次数，失败不写回陌生对象；Windows 光标也由同一管理器资源路径处理。这里改变本地显示，不改游戏代码或仿真任务。','cursor/source/hide.cpp'),
'F57':('游戏内光标刷新','外部宿主经唯一 host_game_input 校验窗口与前台后发送 WM_SETCURSOR；等待有界且不持调度锁。游戏线程上的光标资源发布仍由 GameRuntime 消费。','shared/source/host_game_input.h; cursor/source/hide.cpp'),
'F63':('Shift5','修复设置处理器检查已删除 clickHook 句柄而误关并保存连点的问题，勾选状态直接决定启用。按键观察在低显示帧率下仍按最多 4 ms 目标间隔运行，复用原有计时器，高帧率绘制不降速。旧 INI 的关闭值保留，受影响者重新勾选即可恢复，避免替用户强行打开。自动模式检测到 Ares 时交由原版；无法确定时仍跳过，必要时用户可选强制补点。删除光标模块自己的 WH_MOUSE_LL。通过现有宿主循环观察物理左键边沿，检查 Shift、区域及 Ares 原生支持；额外点击仍由唯一 host_game_input::clickPair 发送且配平抬起。轮询可能漏掉极短点击，不拦截原版点击。','cursor/source/main.cpp; shared/source/host_game_input.h'),
'F67':('一页控制台与当前状态','快捷键字段读取当前 HKM_GETHOTKEY 自绘，保留原生输入/通知；首绘和失焦也显示值。光标主页及高级设置改用公共按钮、开关与配色，固定展开宽度。沿用即时保存与一页滚动，旧帧入口只显示统一消息模式。','assist/source/main.cpp; assist/source/extra_controls.h; shared/source/modern_ui.h')}
features=[]
for f in old:
 ident=f['id'];name,impl,source=changes.get(ident,(f['name'],f['implementation'],f['source']))
 if ident in ('F36','F37','F39'):route='停用：不提供原版规则/身份绕过'
 elif ident in ('F22','F23','F24','F25'):route='宿主输入意图 → 原版 Move 观察（右键）/主动命令（中键）→ 统一事件入口'
 elif ident in ('F30','F31','F32','F33','F34','F35'):route='中键/侧键意图 → GameRuntime 查询/复核 → 原有规划或统一事件入口'
 elif ident in ('F01','F02','F03','F38','F42','F43','F44','F45','F46','F47','F48','F49','F50','F51','F53','F54','F56','F58','F59','F60','F61','F62','F64','F65','F66','F67'):route='读取/外部展示/配置资源；无游戏函数拦截'
 else:route='统一管理器原版调用或事件入口；无功能级 Hook'
 features.append({'id':ident,'name':name,'implementation':impl,'source':source,'route':route,'review':'源码路径审查；局部行为测试见报告，未做全部功能游戏实机验收'})
filters={
 'F10':'可通过功能单位清单限制可维修建筑类型，原有不可维修建筑许可独立生效。',
 'F17':'装车乘员和载具可分别配置类型清单，仍要求原版进入合法性、容量与体积允许。',
 'F18':'重试前复核当前类型清单；清单撤销不会撤回已经进入原版队列的 Enter。',
 'F19':'可配置允许卸载的载具类型；乘员清单控制后续自动任务，不改变原版整车卸载行为。',
 'F20':'可配置允许执行下车后续任务的乘员类型。',
 'F21':'载具与乘员类型分别可配置。仍然只登记当前选中的己方载具；撤销类型后停止后续跟踪。',
 'F24':'高级移动攻击源单位类型可独立配置；捕获与提交旧计划前均复核清单。',
 'F25':'磁电源单位类型可配置；仍要求原版磁力武器和 Locomotor 弹头，清单不赋予新武器。',
 'F30':'源乘员和目标建筑/载具均可配置类型；同类目标分配、容量和原版进入判断保留。',
 'F31':'飞机源单位类型可配置；仍须是原版飞机或符合原有空中状态的载具，并具备兼容武器。',
 'F33':'飞碟源单位类型可配置；保留飞碟 ID 或原版吸取副武器识别，不赋予普通载具新能力。',
 'F35':'可配置允许出售的己方载具类型；仍须满足原版所在格有建筑等出售条件。'}
for f in features:
 if f['id'] in filters and filters[f['id']] not in f['implementation']:f['implementation']+=' '+filters[f['id']]
features=[f for f in features if f['id'] not in ('F68','F69','F70')]
features.append({'id':'F68','name':'各功能单位类型清单','implementation':'统一配置 14 项独立类型清单：飞机、飞碟、磁电、高级移动、装车乘员/载具、进驻乘员/目标、卸载载具/乘员后续任务、逃生载具/乘员、变卖战车、维修建筑。面板选择功能后编辑 ID 列表；每项自定义开关独立。未勾选保留原有识别；勾选且清单为空不处理任何类型。最多 512 项、每项 23 个 ASCII 字符，支持大小写归一、去重与中文分隔符。离线编辑、即时生效、自动保存；配置半写或损坏拒绝发令。只筛选类型，不写原版规则，不绕过所有权/武器/容量/进入合法性。矿车、矿场、自动 CS 与组合选兵沿用各自配置。','source':'assist/source/feature_type_config.h; feature_type_bridge.h; auto_settings_ui.h; type_bindings_ui.h; extra_settings_io.h','route':'EXE 配置 → Shared 版本化快照 → 唯一 GameRuntime 在捕获与提交前复核','review':'便携解析/实际 UI 处理器及 x86 DLL 模型；未做游戏实机全功能验收'})
features.append({'id':'F69','name':'敌方位置标记','implementation':'显示设置中的“敌方位置标记（包含未揭示区域）”默认关闭，修改即时生效并自动保存。复用统一读取器已有对象遍历，按当前玩家的敌我关系筛选存活单位和建筑，不检查地图是否揭示；排除己方、盟友、中立及已进入运输工具的乘员。当前战场视口内按玩家颜色绘制位置符号与 类型名称，建筑方框、其他单位菱形；不绘制到侧栏。跟随覆盖层现有 FPS 设置，使用同一采样时钟、Motion 插值和绘制窗口，同一逻辑帧内继续更新坐标。类型名称及文字位图缓存，最多 2048 个标记；菜单、失焦、跨局、读取失效或数据过期时隐藏，发布前复核当前帧、玩家、镜头和显示状态。仅显示游戏内存已有且布局可识别的对象，不创造未加载的数据。不改变战争迷雾、不调用地图揭示、不写游戏状态、不提交事件或新增 Hook。','source':'external_reader/source/enemy_markers.h; external_reader/source/tactical_sampler.h; assist/source/main.cpp; assist/source/extra_controls.h; assist/source/extra_settings_io.h','route':'统一 ReadSession → TacticalSampler → 现有 Motion 与覆盖层；宿主只读展示，不进入 GameRuntime 命令通道','review':'实际采样器与 Motion 的便携内存模型、生产绘制函数的 GDI 记录模型、设置/UI 检查；尚未验证 Windows 游戏画面与实际 FPS'})
features.append({'id':'F70','name':'热键冲突时全部执行','implementation':'战术面板新增独立开关，默认关闭，即时生效并自动保存到 [Hotkeys] ExecuteAllMatches。开启后，同一键盘组合只注册一次 Windows 热键，再按现有顺序将全部匹配动作放入宿主队列，逐项等待命令/选兵回执，避免后写覆盖；组合选兵仍按类型合并，两种双按状态独立。增强鼠标按每项按钮、按住键和功能许可收集全部匹配项，最多十项；全部绑定同一次捕获的来源时间、选区、目标、对局和取消代次，经同一指针邮箱依次提交。前一协同请求被规划器消费且回执完成后才切换模式，不覆盖未处理请求。不改写原版点击或事件，不绕过每帧额度与原版合法性；同一单位的后续命令可能覆盖前项，持续规划仍只保留最后一项。键盘待发队列上限128、时效2500ms；鼠标首项150ms内接收，已接收组合的后续项共用原有1500ms/90帧总期限，不刷新捕获时间。新操作、菜单、失焦、跨局或配置变化取消未提交鼠标项。关闭开关恢复原有单项规则，保存的重复绑定不被改写。其他程序占用的系统热键仍可能注册失败，面板会报告。Assist 协议42要求整包更新。','source':'assist/source/hotkey_routes.h; hotkey_host.h; pointer_intent.h; pointer_batch.h; pointer_host.h; pointer_bridge.h; auto_settings_ui.h; extra_settings_io.h','route':'一次宿主捕获 → 有界队列 → 现有命令/选兵/指针邮箱 → 单一 GameRuntime 与原版构造器；无新增 Hook','review':'生产键盘/鼠标宿主调度模型、实际x86 DLL同帧额度/续项身份/取消/目标与期限回归；未做真实Windows游戏或平台联机验收'})
assert len(features)==70 and len({f['id'] for f in features})==70
(R/'FEATURE_CATALOG.json').write_text(json.dumps({'version':VERSION,'architecture':'No feature detours; sole manager Windows message entry','features':features},ensure_ascii=False,indent=2)+'\n')
